"""Presentation-only localization, including labels regenerated by tick formatters."""
from matplotlib.backends.backend_qtagg import FigureCanvasQTAgg as QtCanvas
from matplotlib.text import Text
from matplotlib.ticker import Formatter
from .i18n import _bound, tr, tr_items


class LocalizedFormatter(Formatter):
    """Delegate all numeric/date formatting, then translate its displayed text."""
    def __init__(self, base):
        self.base = base

    def __call__(self, x, pos=None):
        return tr(self.base(x, pos))

    def set_axis(self, axis):
        super().set_axis(axis)
        self.base.set_axis(axis)

    def set_locs(self, locs):
        super().set_locs(locs)
        self.base.set_locs(locs)

    def format_ticks(self, values):
        return tr_items(self.base.format_ticks(values))

    def get_offset(self):
        return tr(self.base.get_offset())

    def format_data(self, value):
        return tr(self.base.format_data(value))

    def format_data_short(self, value):
        return tr(self.base.format_data_short(value))

    def _set_locator(self, locator):
        self.base._set_locator(locator)


class FigureCanvasQTAgg(QtCanvas):
    def draw(self):
        for axes in self.figure.axes:
            for axis in (axes.xaxis, axes.yaxis):
                for which in ('major', 'minor'):
                    formatter = getattr(axis, f'get_{which}_formatter')()
                    if not isinstance(formatter, LocalizedFormatter):
                        # Preserve Matplotlib's default-formatter policy for later
                        # scale changes and data updates; locators/values are intact.
                        flag = getattr(axis, f'isDefault_{which[:3]}fmt')
                        getattr(axis, f'set_{which}_formatter')(LocalizedFormatter(formatter))
                        setattr(axis, f'isDefault_{which[:3]}fmt', flag)
        for text in self.figure.findobj(match=Text):
            text.set_text(_bound(text, 'text', text.get_text()))
        super().draw()
